"""Compare the actual Windows checkout and generated bytes for PR #275."""

import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
from urllib.parse import urlsplit
from urllib.request import url2pathname

STOCK = "14a10e44f636caafa6a2c589b7da9d4a02e5e31c"
FIX = "9d908c42835e0c00cfb195ff9cede3b4b6d3e2c2"
WORK = Path(os.environ["RUNNER_TEMP"]) / "prepend-windows"
BAZEL = shutil.which("bazel") or shutil.which("bazelisk")
EXAMPLES = Path.cwd() / "examples"
GOLDEN = "examples/prepend/expected.txt"
TARGETS = ["//prepend:order_test", "//prepend:empty_test"]
EXPECTED = b"first\nsecond\noriginal\n"
REPORT = {"stock": STOCK, "fix": FIX, "cells": {}}


def write():
    (WORK / "result.json").write_text(json.dumps(REPORT, indent=2) + "\n")


def git(*args):
    return subprocess.check_output(["git", *args], text=True).strip()


def record(data):
    return {"hex": data.hex(), "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}


def run(name, revision):
    git("switch", "--detach", revision)
    # Materialize the unchanged blob under this commit's actual checkout attributes.
    Path(GOLDEN).unlink()
    git("checkout-index", "--", GOLDEN)
    assert git("rev-parse", "HEAD") == revision
    golden = Path(GOLDEN).read_bytes()
    row = REPORT["cells"][name] = {
        "head": revision, "blob": git("rev-parse", "HEAD:" + GOLDEN),
        "eol": git("ls-files", "--eol", "--", GOLDEN), "working_tree": record(golden),
        "autocrlf": subprocess.run(["git", "config", "--get", "core.autocrlf"], capture_output=True, text=True).stdout.strip(),
    }
    write()
    bep = WORK / (name + ".bep")
    flags = ["--config=ci", "--remote_cache=", "--remote_executor=", "--bes_backend="]
    log = WORK / (name + ".log")
    with log.open("wb") as out:
        rc = subprocess.run([BAZEL, "test", *flags, "--nocache_test_results", "--flaky_test_attempts=1",
                             "--keep_going", "--build_event_json_file=" + str(bep), *TARGETS],
                            cwd=EXAMPLES, stdout=out, stderr=subprocess.STDOUT).returncode
    row["bazel_exit"] = rc
    row["tests"] = {}
    write()
    for line in bep.read_text(encoding="utf-8").splitlines():
        event = json.loads(line)
        if "started" in event:
            row["invocation"] = event["started"]["uuid"]
        if "testResult" not in event:
            continue
        key, result = event["id"]["testResult"], event["testResult"]
        label = key["label"]
        assert label in TARGETS and label not in row["tests"]
        log_file, = [f for f in result["testActionOutput"] if f["name"] == "test.log"]
        url = urlsplit(log_file["uri"])
        assert url.scheme == "file" and not url.netloc
        data = Path(url2pathname(url.path)).read_bytes()
        assert len(data) < 65536
        digest = hashlib.sha256(data).hexdigest()
        assert log_file.get("digest", digest) == digest and int(log_file.get("length", len(data))) == len(data)
        row["tests"][label] = {"status": result["status"],
                               "cached": bool(result.get("cachedLocally") or result.get("executionInfo", {}).get("cachedRemotely")),
                               "config": key["configuration"]["id"], "attempt": int(key.get("attempt", 1)),
                               "log_sha256": digest,
                               "message": [s.strip() for s in data.decode(errors="replace").splitlines() if "FAIL: files" in s]}
        write()
    if set(row["tests"]) != set(TARGETS):
        row["diagnostics"] = [l[:400] for l in log.read_text(errors="replace").splitlines() if "ERROR:" in l][:8]
        write()
    assert set(row["tests"]) == set(TARGETS)
    selected, = subprocess.check_output([BAZEL, "cquery", *flags, "--output=files", "//prepend:twice"],
                                        cwd=EXAMPLES, text=True).splitlines()
    execution_root = subprocess.check_output([BAZEL, "info", "execution_root"], cwd=EXAMPLES, text=True).strip()
    output = Path(execution_root, selected).read_bytes()
    row.update(generated_file=selected, generated=record(output))
    write()
    assert output == EXPECTED
    assert all(not t["cached"] and t["attempt"] == 1 for t in row["tests"].values())
    assert row["tests"][TARGETS[1]]["status"] == "PASSED"
    if name == "stock":
        assert rc == 3 and row["tests"][TARGETS[0]]["status"] == "FAILED"
        assert any("prepend/expected.txt" in s and "prepend/options.txt" in s
                   for s in row["tests"][TARGETS[0]]["message"])
        assert golden == EXPECTED.replace(b"\n", b"\r\n") and "w/crlf" in row["eol"]
    else:
        assert rc == 0 and row["tests"][TARGETS[0]]["status"] == "PASSED"
        assert golden == EXPECTED and "w/lf" in row["eol"]
    row["verified"] = True
    write()


def main():
    WORK.mkdir()
    assert git("rev-parse", "HEAD^") == FIX and git("rev-parse", "HEAD^^") == STOCK
    assert git("diff", "--name-only", STOCK, FIX) == ".gitattributes"
    assert git("diff", "--name-only", FIX, "HEAD").splitlines() == [
        ".github/qualification/prepend_windows.py", ".github/workflows/prepend-windows-checkout.yml"]
    assert os.name == "nt" and BAZEL
    os.environ["USE_BAZEL_VERSION"] = "9.3.2"
    REPORT["bazel"] = subprocess.check_output([BAZEL, "--version"], cwd=EXAMPLES, text=True).strip()
    assert REPORT["bazel"] == "bazel 9.3.2", REPORT["bazel"]
    write()
    for name, rev in (("stock", STOCK), ("fixed", FIX)):
        try:
            run(name, rev)
        except Exception as e:
            REPORT.setdefault("errors", {})[name] = f"{type(e).__name__}: {e}"[:450]
            write()
    rows = REPORT["cells"]
    assert not REPORT.get("errors"), REPORT.get("errors")
    assert rows["stock"]["blob"] == rows["fixed"]["blob"] and rows["stock"]["generated"] == rows["fixed"]["generated"]
    REPORT["verified"] = True
    write()


if __name__ == "__main__":
    main()
